/// <summary>
/// This is a data contract class for the business event <c>METInventTransferOrderPostingInfoBusinessEvent</c>.
/// </summary>
[DataContractAttribute]
class METInventTransferOrderPostingInfoContract extends BusinessEventsContract
{
    #define.InventJournalId('Journal Id')
    #define.status('Status')
    #define.DateAndTime('Date time')

    private InventJournalId        journalId;
    private JournalPosted          status;
    private JournalPostedDateTime  dateTime;

}

