/// <summary>
///  Constructs a <c>METInventTransferOrderPostingInfoContract</c>.
/// </summary>
/// <param name = "_journalTable">
/// <c>InventJournalTable</c> record.
/// </param>
/// <returns>An instance of <c>METInventTransferOrderPostingInfoContract</c>.</returns>
public static METInventTransferOrderPostingInfoContract newFromInventTransferOrder(InventJournalTable _journalTable)
{
    var contract = new METInventTransferOrderPostingInfoContract();
    contract.initialize(_journalTable);

    return contract;
}

/// <summary>
/// Initializes data variables.
/// </summary>
/// <param name = "_journalTable">
/// <c>InventJournalTable</c> record.
/// </param>
public void initialize(InventJournalTable _journalTable)
{
    journalId = _journalTable.JournalId;
    status    = _journalTable.Posted;
    dateTime  = _journalTable.PostedDateTime;
}

/// <summary>
/// Gets and sets Invent journal number.
/// </summary>
/// <param name = "_journalId">Invent journal number.</param>
/// <returns>Invent journal number.</returns>
[DataMember(#InventJournalId),BusinessEventsDataMember("Journal Id")]
public InventJournalId parmJournalId(InventJournalId _journalId = journalId)
{
    journalId = _journalId;
    return journalId;
}

/// <summary>
/// Gets and sets Invent journal status.
/// </summary>
/// <param name = "_status">Invent journal status.</param>
/// <returns>Invent journal status.</returns>
[DataMember(#status),BusinessEventsDataMember("Status")]
public JournalPosted parmInventTransferStatus(JournalPosted _status = status)
{
    status = _status;
    return status;
}

/// <summary>
/// Gets and sets Invent journal posting date and time.
/// </summary>
/// <param name = "_dateTime">Invent journal posting date and time.</param>
/// <returns>Invent journal posting date and time.</returns>
[DataMember(#DateAndTime),BusinessEventsDataMember("Date time")]
public JournalPostedDateTime parmJournalPostedDateTime(JournalPostedDateTime _dateTime = dateTime)
{
    dateTime = _dateTime;
    return  dateTime;
}
